#!/usr/bin/env python3
"""把布局配色从"我们主题派生"改成**拆包得到的真实品牌色板**。

来源：四个 APK 的 resources.arsc（int color 项）——
  CapCut    #FFFFFF / #FAFBFF / #090C14 / #6B7079 / #E7E9EF / **#00CAE0**
  快影       #FFFFFF / #FFFFFF / #222222 / #666666 / #E6E6E6 / **#FF5000**
  AM        #FFFFFF / #F7F8FC / #1F2238 / #6B6E85 / #E3E4EC / **#F16586**
  Blurrr    #121214 / #17171A / #F2F2F5 / #9A9AA2 / #2A2A30 / **#03DAC6**

这些值直接写进 tokens（app_bg / panel_bg / text / text_dim / separator / field_bg / row_alt /
accent / cti / timecode …），不再读用户主题色；ae 布局仍然回到用户自己的主题。
"""
from __future__ import annotations

import os
from pathlib import Path

MARKER = "EFFECTCRAFT_OURS_BRAND_PALETTE_V1"

OLD = '        // EFFECTCRAFT_OURS_LAYOUT_BRAND_ACCENT_V1 — 布局自带主题色系 + 品牌主色。\n        // 不需要新增状态：用 tokens 当前值判断是否已经应用到目标。\n        {\n            let ws = self.ui.workspace.as_str().to_string();\n            let light_layout = matches!(ws.as_str(), "capcut" | "kuaishou" | "am");\n            let brand: Option<egui::Color32> = match ws.as_str() {\n                "capcut" => Some(egui::Color32::from_rgb(0x3d, 0x9b, 0xff)),\n                "kuaishou" => Some(egui::Color32::from_rgb(0xff, 0x5a, 0x5a)),\n                "am" => Some(egui::Color32::from_rgb(0x00, 0xd6, 0xb4)),\n                _ => None,\n            };\n            let want = if light_layout {\n                crate::theme::ThemeKind::Light\n            } else {\n                self.ui.theme\n            };\n            let brand_colors = [\n                egui::Color32::from_rgb(0x3d, 0x9b, 0xff),\n                egui::Color32::from_rgb(0xff, 0x5a, 0x5a),\n                egui::Color32::from_rgb(0x00, 0xd6, 0xb4),\n            ];\n            let branded = brand_colors.contains(&self.tokens.accent);\n            let needs = match brand {\n                Some(c) => self.tokens.kind != want || self.tokens.accent != c,\n                None => self.tokens.kind != want || branded,\n            };\n            if needs {\n                let mut t = Tokens::from_prefs(&self.session.prefs, want);\n                if let Some(c) = brand {\n                    t.accent = c;\n                    t.focus = c;\n                    t.accent_hover = c.lerp_to_gamma(egui::Color32::WHITE, 0.22);\n                    t.cti = c;\n                    t.timecode = c;\n                    t.hot_text = c;\n                    t.keyframe_selected = c;\n                }\n                self.tokens = t;\n                crate::theme::apply_visuals(&ctx, &self.tokens);\n                ctx.set_theme(crate::theme::theme_preference(\n                    &self.session.prefs.appearance.appearance_mode,\n                    want.is_light(),\n                ));\n            }\n        }'

NEW = '        // EFFECTCRAFT_OURS_BRAND_PALETTE_V1 — 每套布局用**拆包得到的真实配色**，不再从我们自己的主题派生。\n        // 颜色取自各家 APK 的 resources.arsc（见 HANDOFF「品牌配色来源」）：\n        //   CapCut   白底 #FFFFFF / 近白面 #FAFBFF / 文字 #090C14 / 强调 #00CAE0（青）\n        //   快影      白底 #FFFFFF / 文字 #222222 / 次要 #666666 / 分隔 #E6E6E6 / 强调 #FF5000（橙）\n        //   AM       白底 #FFFFFF / 面 #F7F8FC / 文字 #1F2238 / 强调 #F16586（粉）\n        //   Blurrr   深底 #121214 / 面 #17171A / 文字 #F2F2F5 / 强调 #03DAC6（青绿）\n        {\n            let ws = self.ui.workspace.as_str().to_string();\n            let c = egui::Color32::from_rgb;\n            let pal: Option<(bool, [egui::Color32; 8])> = match ws.as_str() {\n                "capcut" => Some((\n                    true,\n                    [\n                        c(0xFF, 0xFF, 0xFF), // app_bg\n                        c(0xFA, 0xFB, 0xFF), // panel_bg\n                        c(0x09, 0x0C, 0x14), // text\n                        c(0x6B, 0x70, 0x79), // text_dim\n                        c(0xE7, 0xE9, 0xEF), // separator\n                        c(0x00, 0xCA, 0xE0), // accent\n                        c(0xF3, 0xF5, 0xF9), // field_bg\n                        c(0xF6, 0xF7, 0xFE), // row_alt\n                    ],\n                )),\n                "kuaishou" => Some((\n                    true,\n                    [\n                        c(0xFF, 0xFF, 0xFF),\n                        c(0xFF, 0xFF, 0xFF),\n                        c(0x22, 0x22, 0x22),\n                        c(0x66, 0x66, 0x66),\n                        c(0xE6, 0xE6, 0xE6),\n                        c(0xFF, 0x50, 0x00),\n                        c(0xF5, 0xF5, 0xF5),\n                        c(0xFA, 0xFA, 0xFA),\n                    ],\n                )),\n                "am" | "jianying" => Some((\n                    true,\n                    [\n                        c(0xFF, 0xFF, 0xFF),\n                        c(0xF7, 0xF8, 0xFC),\n                        c(0x1F, 0x22, 0x38),\n                        c(0x6B, 0x6E, 0x85),\n                        c(0xE3, 0xE4, 0xEC),\n                        c(0xF1, 0x65, 0x86),\n                        c(0xF5, 0xF6, 0xFA),\n                        c(0xF2, 0xF3, 0xF9),\n                    ],\n                )),\n                "blurrr" => Some((\n                    false,\n                    [\n                        c(0x12, 0x12, 0x14),\n                        c(0x17, 0x17, 0x1A),\n                        c(0xF2, 0xF2, 0xF5),\n                        c(0x9A, 0x9A, 0xA2),\n                        c(0x2A, 0x2A, 0x30),\n                        c(0x03, 0xDA, 0xC6),\n                        c(0x1E, 0x1E, 0x22),\n                        c(0x1A, 0x1A, 0x1D),\n                    ],\n                )),\n                _ => None,\n            };\n            // 品牌色用于判断"当前 tokens 是否已经被某套布局改过"\n            let brand_accents = [\n                c(0x00, 0xCA, 0xE0),\n                c(0xFF, 0x50, 0x00),\n                c(0xF1, 0x65, 0x86),\n                c(0x03, 0xDA, 0xC6),\n            ];\n            let branded = brand_accents.contains(&self.tokens.accent);\n            let wants = match pal {\n                Some((light, [bg, panel, text, dim, sep, accent, field, alt])) => {\n                    let kind_ok = self.tokens.kind.is_light() == light;\n                    let same = kind_ok\n                        && self.tokens.app_bg == bg\n                        && self.tokens.panel_bg == panel\n                        && self.tokens.text == text\n                        && self.tokens.accent == accent\n                        && self.tokens.separator == sep\n                        && self.tokens.field_bg == field\n                        && self.tokens.row_alt == alt\n                        && self.tokens.text_dim == dim;\n                    if same {\n                        None\n                    } else {\n                        Some((light, [bg, panel, text, dim, sep, accent, field, alt]))\n                    }\n                }\n                None => {\n                    if branded\n                        || self.tokens.kind.is_light() != self.ui.theme.is_light()\n                        || self.tokens.app_bg != Tokens::from_prefs(&self.session.prefs, self.ui.theme).app_bg\n                    {\n                        Some((self.ui.theme.is_light(), [egui::Color32::TRANSPARENT; 8]))\n                    } else {\n                        None\n                    }\n                }\n            };\n            if let Some((light, [bg, panel, text, dim, sep, accent, field, alt])) = wants {\n                let kind = if light {\n                    crate::theme::ThemeKind::Light\n                } else {\n                    crate::theme::ThemeKind::Dark\n                };\n                let mut t = Tokens::from_prefs(&self.session.prefs, kind);\n                if accent != egui::Color32::TRANSPARENT {\n                    t.app_bg = bg;\n                    t.panel_bg = panel;\n                    t.header_bg = panel;\n                    t.text = text;\n                    t.text_dim = dim;\n                    t.text_faint = dim.gamma_multiply(0.75);\n                    t.separator = sep;\n                    t.field_bg = field;\n                    t.field_border = sep;\n                    t.row = bg;\n                    t.row_alt = alt;\n                    t.row_selected = accent.gamma_multiply(0.18);\n                    t.tl_bg = bg;\n                    t.tl_ruler_bg = panel;\n                    t.switch_well = field;\n                    t.accent = accent;\n                    t.focus = accent;\n                    t.accent_hover = accent.lerp_to_gamma(egui::Color32::WHITE, 0.22);\n                    t.cti = accent;\n                    t.timecode = accent;\n                    t.hot_text = accent;\n                    t.keyframe_selected = accent;\n                }\n                self.tokens = t;\n                crate::theme::apply_visuals(&ctx, &self.tokens);\n                ctx.set_theme(crate::theme::theme_preference(\n                    &self.session.prefs.appearance.appearance_mode,\n                    self.tokens.kind.is_light(),\n                ));\n            }\n        }'


def main() -> None:
    root = Path(os.environ["EFFECTCRAFT_DIR"]).resolve()
    path = root / "crates/ui-egui/src/app/frame.rs"
    src = path.read_text(encoding="utf-8")
    if MARKER in src:
        print("brand palette already present")
        return
    if src.count(OLD) != 1:
        raise SystemExit(f"anchor: {{src.count(OLD)}}")
    path.write_text(src.replace(OLD, NEW, 1), encoding="utf-8")
    print("layouts use palettes extracted from the real apps")


if __name__ == "__main__":
    main()
